begin;
create table if not exists public.angelcare_marketplace_analytics_metric_definitions(id uuid primary key default gen_random_uuid(),metric_key text unique not null,name_fr text not null,domain text not null,description_fr text not null,source_tables text[] not null,calculation_definition text not null,unit text not null,territory_aware boolean not null default true,tenant_aware boolean not null default true,owner_role text not null,refresh_frequency text not null,status text not null default 'active',version int not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_analytics_snapshots(id uuid primary key default gen_random_uuid(),metric_key text not null references public.angelcare_marketplace_analytics_metric_definitions(metric_key),territory_id uuid,tenant_id uuid,period_start timestamptz not null,period_end timestamptz not null,value_numeric numeric(20,4),value_text text,dimensions jsonb not null default '{}',source_count int not null default 0,excluded_count int not null default 0,data_quality_status text not null default 'accepted',calculated_at timestamptz not null default now(),definition_version int not null,unique(metric_key,territory_id,tenant_id,period_start,period_end,calculated_at));
create table if not exists public.angelcare_marketplace_analytics_data_quality_events(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('DQ-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),metric_key text,domain text not null,event_type text not null,severity text not null,status text not null default 'open',description text not null,affected_records int not null default 0,owner_id uuid,detected_at timestamptz not null default now(),resolved_at timestamptz,resolution_note text);
create table if not exists public.angelcare_marketplace_security_access_reviews(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('AR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),review_type text not null,subject_type text not null,subject_id uuid not null,territory_id uuid,tenant_id uuid,reviewer_id uuid,status text not null default 'open',risk_level text not null default 'standard',permissions_snapshot text[] not null default '{}',findings text[] not null default '{}',decision text,due_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_security_isolation_tests(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('ISO-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),test_scope text not null,actor_profile text not null,resource_domain text not null,territory_id uuid,tenant_id uuid,expected_result text not null check(expected_result in('allow','deny')),observed_result text,status text not null default 'not_run' check(status in('not_run','passed','failed','blocked','expired')),evidence jsonb not null default '{}',executed_by uuid,executed_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_security_events(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('SEC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),event_type text not null,severity text not null,status text not null default 'open',actor_id uuid,territory_id uuid,tenant_id uuid,object_type text,object_id uuid,request_id text,description text not null,detected_at timestamptz not null default now(),resolved_at timestamptz,owner_id uuid);
create table if not exists public.angelcare_marketplace_security_retention_policies(id uuid primary key default gen_random_uuid(),policy_key text unique not null,domain text not null,record_type text not null,retention_days int,legal_hold_supported boolean not null default true,deletion_mode text not null,archive_mode text not null,territory_id uuid,status text not null default 'active',owner_role text not null,last_reviewed_at timestamptz,next_review_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_backup_register(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('BKP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),backup_type text not null,system_scope text not null,status text not null default 'planned' check(status in('planned','in_progress','completed','validated','failed','expired')),started_at timestamptz not null,completed_at timestamptz,retention_until timestamptz,encrypted boolean not null default true,checksum text,storage_reference text,owner_id uuid,failure_reason text,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_recovery_tests(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('RCT-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,11))),backup_id uuid references public.angelcare_marketplace_backup_register(id),environment_type text not null,status text not null default 'planned' check(status in('planned','authorized','in_progress','restored','validated','failed','corrective_action_required','approved','closed')),recovery_point_objective_minutes int not null,recovery_time_objective_minutes int not null,actual_recovery_point_minutes int,actual_recovery_time_minutes int,authorized_by uuid,executed_by uuid,validated_by uuid,evidence jsonb not null default '{}',planned_at timestamptz,started_at timestamptz,completed_at timestamptz,next_action text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.angelcare_marketplace_analytics_metric_definitions(metric_key,name_fr,domain,description_fr,source_tables,calculation_definition,unit,owner_role,refresh_frequency) values
('commercial.contracted_value','Valeur contractualisée','commercial','Somme nette des revenue streams contractualisés.',array['angelcare_marketplace_finance_revenue_streams']::text[],'SUM(net_amount) WHERE status IN contracted,scheduled','Dh','commercial_director','hourly'),('family.active_accounts','Familles actives','families','Comptes familles actifs.',array['angelcare_marketplace_family_accounts']::text[],'COUNT(accounts) WHERE status active','count','family_operations','daily'),('b2b.active_programs','Programmes B2B actifs','b2b','Programmes B2B actifs.',array['angelcare_marketplace_b2b_programs']::text[],'COUNT(programs) WHERE status active','count','b2b_director','hourly'),('academy.completion_rate','Completion Academy','academy','Taux de cohortes complétées.',array['angelcare_marketplace_academy_enrollments']::text[],'completed / enrolled * 100','percent','academy_director','daily'),('providers.eligible_count','Providers éligibles','providers','Providers opérationnellement éligibles.',array['angelcare_marketplace_provider_operational_eligibility']::text[],'COUNT(eligibility) WHERE status eligible','count','workforce_director','hourly'),('operations.validated_missions','Missions validées','operations','Missions validées sur la période.',array['angelcare_marketplace_operations_missions']::text[],'COUNT(missions) WHERE status validated or closed','count','operations_manager','hourly'),('trust.health_score','Trust health','trust','Score dérivé des findings, plaintes, CAPA et preuves.',array['angelcare_marketplace_quality_findings','angelcare_marketplace_complaints','angelcare_marketplace_quality_corrective_actions']::text[],'100 - weighted blockers','percent','trust_quality_director','hourly'),('finance.invoice_ready_value','Valeur invoice-ready','finance','Somme des dossiers ready.',array['angelcare_marketplace_finance_invoice_readiness']::text[],'SUM(amount) WHERE status ready','Dh','finance_director','hourly') on conflict(metric_key) do update set name_fr=excluded.name_fr,source_tables=excluded.source_tables,calculation_definition=excluded.calculation_definition,version=public.angelcare_marketplace_analytics_metric_definitions.version+1,updated_at=now();
create or replace function public.angelcare_marketplace_refresh_analytics(p_territory_id uuid,p_tenant_id uuid,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare start_at timestamptz:=date_trunc('day',now());finish_at timestamptz:=now();n int:=0;begin insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'commercial.contracted_value',p_territory_id,p_tenant_id,start_at,finish_at,coalesce(sum(net_amount),0),count(*),1 from public.angelcare_marketplace_finance_revenue_streams where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id) and status in('contracted','scheduled');n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'family.active_accounts',p_territory_id,p_tenant_id,start_at,finish_at,count(*),count(*),1 from public.angelcare_marketplace_family_accounts where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id);n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'b2b.active_programs',p_territory_id,p_tenant_id,start_at,finish_at,count(*),count(*),1 from public.angelcare_marketplace_b2b_programs where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id) and status='active';n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'academy.completion_rate',p_territory_id,p_tenant_id,start_at,finish_at,case when count(*)=0 then 0 else count(*) filter(where status='completed')::numeric/count(*)*100 end,count(*),1 from public.angelcare_marketplace_academy_enrollments where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id);n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'providers.eligible_count',p_territory_id,p_tenant_id,start_at,finish_at,count(*),count(*),1 from public.angelcare_marketplace_provider_operational_eligibility where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id) and status in('eligible','eligible_with_restrictions');n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'operations.validated_missions',p_territory_id,p_tenant_id,start_at,finish_at,count(*),count(*),1 from public.angelcare_marketplace_operations_missions where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id) and status in('validated','payable_handover','closed');n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'trust.health_score',p_territory_id,p_tenant_id,start_at,finish_at,greatest(0,100-count(*) filter(where critical_flag)*15),count(*),1 from public.angelcare_marketplace_quality_findings;n:=n+1;insert into public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,period_start,period_end,value_numeric,source_count,definition_version) select 'finance.invoice_ready_value',p_territory_id,p_tenant_id,start_at,finish_at,coalesce(sum(amount),0),count(*),1 from public.angelcare_marketplace_finance_invoice_readiness where (p_territory_id is null or territory_id=p_territory_id) and (p_tenant_id is null or tenant_id=p_tenant_id) and status='ready';n:=n+1;return jsonb_build_object('snapshotsCreated',n,'calculatedAt',finish_at);end$$;
create or replace function public.angelcare_marketplace_record_isolation_test(p_test_id uuid,p_observed_result text,p_evidence jsonb,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_security_isolation_tests;begin update public.angelcare_marketplace_security_isolation_tests set observed_result=p_observed_result,status=case when expected_result=p_observed_result then 'passed' else 'failed' end,evidence=p_evidence,executed_by=p_actor_id,executed_at=now() where id=p_test_id returning * into r;if r.id is null then raise exception 'Isolation test introuvable';end if;if r.status='failed' then insert into public.angelcare_marketplace_security_events(event_type,severity,status,territory_id,tenant_id,object_type,object_id,description,owner_id) values('isolation_test_failed','critical','open',r.territory_id,r.tenant_id,'security_isolation_test',r.id,'Expected '||r.expected_result||' but observed '||coalesce(r.observed_result,'null'),p_actor_id);end if;return to_jsonb(r);end$$;
create or replace function public.angelcare_marketplace_transition_recovery_test(p_test_id uuid,p_next_status text,p_reason text,p_actor_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_recovery_tests;begin if p_next_status='validated' and not exists(select 1 from public.angelcare_marketplace_recovery_tests where id=p_test_id and actual_recovery_point_minutes is not null and actual_recovery_time_minutes is not null and evidence<>'{}'::jsonb) then raise exception 'Recovery metrics and evidence required';end if;update public.angelcare_marketplace_recovery_tests set status=p_next_status,authorized_by=case when p_next_status='authorized' then p_actor_id else authorized_by end,executed_by=case when p_next_status='in_progress' then p_actor_id else executed_by end,validated_by=case when p_next_status in('validated','approved') then p_actor_id else validated_by end,started_at=case when p_next_status='in_progress' then now() else started_at end,completed_at=case when p_next_status in('validated','failed','approved','closed') then now() else completed_at end,next_action=p_reason,updated_at=now() where id=p_test_id returning * into r;if r.id is null then raise exception 'Recovery test introuvable';end if;return to_jsonb(r);end$$;
insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values ('marketplace.analytics.view','Consulter les analytics','Analytics',false),('marketplace.analytics.executive','Analytics executive','Analytics',false),('marketplace.analytics.finance','Analytics finance','Analytics',false),('marketplace.analytics.security','Analytics security','Analytics',false),('marketplace.analytics.export','Exporter les analytics','Analytics',true),('marketplace.analytics.definitions.manage','Gérer les définitions','Analytics',true),('marketplace.analytics.data_quality.manage','Gérer la data quality','Analytics',true),('marketplace.security.access_review','Réviser les accès','Security',true),('marketplace.security.roles.manage','Gérer les rôles','Security',true),('marketplace.security.isolation.review','Réviser l’isolation','Security',true),('marketplace.security.events.view','Voir les événements sécurité','Security',false),('marketplace.security.retention.manage','Gérer la rétention','Security',true),('marketplace.security.separation_of_duties.review','Réviser séparation des devoirs','Security',true),('marketplace.backup.view','Consulter les backups','Backup',false),('marketplace.backup.manage','Gérer les backups','Backup',true),('marketplace.recovery_test.approve','Approuver recovery test','Backup',true) on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and (p.permission_key like 'marketplace.analytics.%' or p.permission_key like 'marketplace.security.%' or p.permission_key like 'marketplace.backup.%' or p.permission_key like 'marketplace.recovery_test.%') on conflict do nothing;
insert into public.angelcare_marketplace_modules(module_key,name,description,route_prefix,module_type,audience,status,enabled,required_permissions,required_dependencies,territory_aware,tenant_aware,locale_aware,health_status,owner_role,introduced_by_mega_zip) values('analytics-security-assurance','Analytics & Security Assurance','Metric definitions, isolation tests, backups and recovery evidence.','/angelcare-marketplace/admin/analytics','assurance',array['admin','executive']::text[],'enabled',true,array['marketplace.analytics.view']::text[],array['finance-authority','trust-quality-authority']::text[],true,true,true,'healthy','security_analytics_director',20) on conflict(module_key) do update set status='enabled',enabled=true,route_prefix=excluded.route_prefix,required_permissions=excluded.required_permissions,updated_at=now();
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.analytics-security.enabled','Analytics & Security Assurance','Real metrics, isolation and recovery evidence.',true,'active','Ultra Delivery 5/5 · Original MZ20') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
alter table public.angelcare_marketplace_analytics_metric_definitions enable row level security;
alter table public.angelcare_marketplace_analytics_snapshots enable row level security;
alter table public.angelcare_marketplace_analytics_data_quality_events enable row level security;
alter table public.angelcare_marketplace_security_access_reviews enable row level security;
alter table public.angelcare_marketplace_security_isolation_tests enable row level security;
alter table public.angelcare_marketplace_security_events enable row level security;
alter table public.angelcare_marketplace_security_retention_policies enable row level security;
alter table public.angelcare_marketplace_backup_register enable row level security;
alter table public.angelcare_marketplace_recovery_tests enable row level security;
revoke all on table public.angelcare_marketplace_analytics_metric_definitions,public.angelcare_marketplace_analytics_snapshots,public.angelcare_marketplace_analytics_data_quality_events,public.angelcare_marketplace_security_access_reviews,public.angelcare_marketplace_security_isolation_tests,public.angelcare_marketplace_security_events,public.angelcare_marketplace_security_retention_policies,public.angelcare_marketplace_backup_register,public.angelcare_marketplace_recovery_tests from anon,authenticated;
grant all on table public.angelcare_marketplace_analytics_metric_definitions,public.angelcare_marketplace_analytics_snapshots,public.angelcare_marketplace_analytics_data_quality_events,public.angelcare_marketplace_security_access_reviews,public.angelcare_marketplace_security_isolation_tests,public.angelcare_marketplace_security_events,public.angelcare_marketplace_security_retention_policies,public.angelcare_marketplace_backup_register,public.angelcare_marketplace_recovery_tests to service_role;
grant execute on function public.angelcare_marketplace_refresh_analytics(uuid,uuid,uuid),public.angelcare_marketplace_record_isolation_test(uuid,text,jsonb,uuid),public.angelcare_marketplace_transition_recovery_test(uuid,text,text,uuid) to service_role;
create index if not exists ac_snapshot_metric_scope_idx on public.angelcare_marketplace_analytics_snapshots(metric_key,territory_id,tenant_id,calculated_at desc);create index if not exists ac_security_event_scope_idx on public.angelcare_marketplace_security_events(territory_id,tenant_id,severity,status,detected_at desc);
commit;
